'use strict';

const { connect, signers } = require('@hyperledger/fabric-gateway');
const grpc = require('@grpc/grpc-js');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

// Crypto material generated by fabric-network/scripts/network-up.sh.
// A relative FABRIC_CRYPTO_PATH is resolved from the backend folder; if it does
// not exist, fall back to the repository's fabric-network/crypto-config.
const DEFAULT_CRYPTO_PATH = path.resolve(__dirname, '..', '..', '..', 'fabric-network', 'crypto-config');
const CRYPTO_PATH = (() => {
  const configured = process.env.FABRIC_CRYPTO_PATH;
  if (configured) {
    const resolved = path.resolve(__dirname, '..', '..', configured);
    if (fs.existsSync(resolved)) return resolved;
    console.warn(`[Fabric] FABRIC_CRYPTO_PATH ${resolved} not found, using ${DEFAULT_CRYPTO_PATH}`);
  }
  return DEFAULT_CRYPTO_PATH;
})();
const CHANNEL = process.env.FABRIC_CHANNEL || 'docuchain';
const CHAINCODE = process.env.FABRIC_CHAINCODE || 'docuchain-cc';
// Connect through the published Docker port; TLS still checks the peer's real host name
const PEER_ENDPOINT = (process.env.FABRIC_PEER_ENDPOINT || 'localhost:7051').replace(/^grpcs?:\/\//, '');
const PEER_HOST_ALIAS = 'peer0.org1.docuchain.local';

function getTlsCert() {
  return fs.readFileSync(path.join(CRYPTO_PATH, process.env.FABRIC_PEER_TLS_CERT));
}

function getAdminCert() {
  return fs.readFileSync(path.join(CRYPTO_PATH, process.env.FABRIC_ADMIN_CERT));
}

function getAdminKey() {
  const keyDir = path.join(CRYPTO_PATH, process.env.FABRIC_ADMIN_KEY_PATH);
  const keyFile = fs.readdirSync(keyDir)[0];
  return fs.readFileSync(path.join(keyDir, keyFile));
}

async function newGrpcConnection() {
  const tlsCredentials = grpc.credentials.createSsl(getTlsCert());
  return new grpc.Client(PEER_ENDPOINT, tlsCredentials, {
    'grpc.ssl_target_name_override': PEER_HOST_ALIAS,
  });
}

async function getContract(options = {}) {
  const client = await newGrpcConnection();
  const gateway = connect({
    ...options,
    client,
    identity: {
      mspId: process.env.FABRIC_MSP_ID || 'Org1MSP',
      credentials: getAdminCert(),
    },
    signer: signers.newPrivateKeySigner(
      crypto.createPrivateKey(getAdminKey())
    ),
  });

  const network = gateway.getNetwork(CHANNEL);
  const contract = network.getContract(CHAINCODE);
  return { gateway, client, contract, network };
}

async function submitTransaction(fcn, ...args) {
  const { gateway, client, contract } = await getContract();
  try {
    console.log('[Fabric] Submitting:', fcn, args);
    const result = await contract.submitTransaction(fcn, ...args);
    const json = Buffer.from(result).toString();
    console.log('[Fabric] Result:', json);
    return JSON.parse(json);
  } finally {
    gateway.close();
    client.close();
  }
}

async function evaluateTransaction(fcn, ...args) {
  const { gateway, client, contract } = await getContract();
  try {
    console.log('[Fabric] Evaluating:', fcn, args);
    const result = await contract.evaluateTransaction(fcn, ...args);
    const json = Buffer.from(result).toString();
    console.log('[Fabric] Result:', json);
    return JSON.parse(json);
  } finally {
    gateway.close();
    client.close();
  }
}

// ─── Read-only ledger queries (Blockchain Explorer) ───────────────
// Uses the qscc system chaincode, so nothing is written to the ledger.
// Fails fast when the peer is not reachable instead of hanging.
const CONNECT_TIMEOUT_MS = parseInt(process.env.FABRIC_CONNECT_TIMEOUT_MS) || 4000;

function waitForReady(client) {
  return new Promise((resolve, reject) => {
    client.waitForReady(Date.now() + CONNECT_TIMEOUT_MS, (err) => {
      if (err) return reject(new Error(`Fabric peer ${PEER_ENDPOINT} is not reachable (${err.message}).`));
      resolve();
    });
  });
}

/**
 * Open one gateway connection and run several qscc queries on it.
 * @param {(query: (fcn: string, ...args: string[]) => Promise<Buffer>) => Promise<any>} work
 */
async function withLedgerQueries(work) {
  const deadline = () => ({ deadline: Date.now() + 10000 });
  const { gateway, client, network } = await getContract({ evaluateOptions: deadline });
  try {
    await waitForReady(client);
    const qscc = network.getContract('qscc');
    const query = async (fcn, ...args) => {
      const result = await qscc.evaluateTransaction(fcn, CHANNEL, ...args);
      return Buffer.from(result);
    };
    return await work(query);
  } finally {
    gateway.close();
    client.close();
  }
}

module.exports = { submitTransaction, evaluateTransaction, withLedgerQueries, CHANNEL };